import geopandas as gpd

# Load the master GeoJSON generated by your pipeline
gdf = gpd.read_file("data/mosdac_all_cyclones.geojson")

# Ensure CRS is standard WGS84
gdf.set_crs(epsg=4326, allow_override=True, inplace=True)

# Export to ESRI Shapefile and GeoPackage
gdf.to_file("data/mosdac_cyclones.shp")
gdf.to_file("data/mosdac_cyclones.gpkg", driver="GPKG")
print(f"Exported {len(gdf)} waypoints to Shapefile and GeoPackage successfully.")